pub(super) fn pack_directory(owner: &Path, root: &Path, label: &str) -> PathBuf {
    let packed = owner.join(format!("packed-{label}"));
    let cache = owner.join(format!("npm-cache-{label}"));
    fs::create_dir(&packed).unwrap();
    fs::create_dir(&cache).unwrap();
    let output = Command::new("npm.cmd")
        .current_dir(root)
        .arg("pack")
        .arg("--ignore-scripts")
        .arg("--json")
        .arg("--cache")
        .arg(&cache)
        .arg("--pack-destination")
        .arg(&packed)
        .output()
        .unwrap();
    assert!(
        output.status.success(),
        "npm pack failed: {} {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let result: JsonValue = serde_json::from_slice(&output.stdout).unwrap();
    let archive = packed.join(result[0]["filename"].as_str().unwrap());
    assert!(archive.is_file(), "npm pack archive is absent");
    archive
}

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn field_index(entries: &[(Value, Value)], field: &str) -> usize {
    entries
        .iter()
        .position(|(key, _)| key == &Value::Text(field.to_owned()))
        .unwrap()
}

fn nested_field<'a>(value: &'a Value, field: &str) -> &'a Value {
    let Value::Map(entries) = value else {
        panic!("dependency archive entry is not a map")
    };
    &entries[field_index(entries, field)].1
}

fn nested_field_mut<'a>(value: &'a mut Value, field: &str) -> &'a mut Value {
    let Value::Map(entries) = value else {
        panic!("dependency archive entry is not a map")
    };
    let index = field_index(entries, field);
    &mut entries[index].1
}

fn node_executable() -> PathBuf {
    PathBuf::from(std::env::var_os("ProgramFiles").unwrap()).join("nodejs/node.exe")
}

